head.script:
scwin.onpageload = function () {
	imports("uiplugin.popup");
};

scwin.onpageunload = function () {

};


scwin.trigger1_onclick = function (e) {
	var options = {
		id: "popWframe",
		title: "popupTest",
		type: "wframePopup",
		width: "700px",
		height: "500px",
		popupName: "wframePopup"
	};

	$p.openPopup("wframePopup_floatingLayer_WESD-1123_(WSQ-5195)_sub.xml", options);
};

	scwin.checkVal1 = function() {
	debugger;
		return WebSquare.wUnit.getDomById('_modal').style.display == 'block';
	}
	scwin.unitTest = function() {
		//init
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
		WebSquare.wUnit.addCommand("pause", "400");
		//Run  and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest()
